export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  let thresholdsResult = [];
  let allPassed = true;

  if (thresholds && typeof thresholds === 'object') {
    Object.entries(thresholds).forEach(([metricId, min]) => {
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score;
      const passed = score !== null && score !== undefined && score >= min;

      if (!passed) {
        allPassed = false;
      }

      thresholdsResult.push({
        metric: metricId,
        min,
        score: score ?? null,
        passed
      });
    });
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && typeof thresholds === 'object') {
    report.passed = allPassed;
    report.thresholds = thresholdsResult;
  }

  return report;
}

