#!/usr/bin/env node

// Test threshold parsing logic
function parseThresholds(thresholdStrings) {
  if (!thresholdStrings) {
    return { thresholds: undefined };
  }

  const strings = Array.isArray(thresholdStrings) ? thresholdStrings : [thresholdStrings];
  const result = {};
  const validMetrics = ['exact_match', 'toxicity', 'length_variance'];

  for (const str of strings) {
    const match = str.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      return { thresholds: undefined, error: `Malformed threshold "${str}": must be <metric>=<number>` };
    }

    const [, metric, valueStr] = match;
    const value = Number.parseFloat(valueStr);

    if (Number.isNaN(value) || value < 0 || value > 1) {
      return { thresholds: undefined, error: `Invalid threshold value "${valueStr}": must be a number between 0 and 1` };
    }

    if (!validMetrics.includes(metric)) {
      return {
        thresholds: undefined,
        error: `Unknown metric "${metric}". Valid metrics are: ${validMetrics.join(', ')}`
      };
    }

    result[metric] = value;
  }

  return { thresholds: result };
}

// Test cases
const tests = [
  {
    name: 'Valid single threshold',
    input: 'exact_match=0.9',
    expected: { thresholds: { exact_match: 0.9 } }
  },
  {
    name: 'Valid multiple thresholds',
    input: ['exact_match=0.9', 'toxicity=0.95'],
    expected: { thresholds: { exact_match: 0.9, toxicity: 0.95 } }
  },
  {
    name: 'Valid threshold at boundary (0)',
    input: 'exact_match=0',
    expected: { thresholds: { exact_match: 0 } }
  },
  {
    name: 'Valid threshold at boundary (1)',
    input: 'exact_match=1',
    expected: { thresholds: { exact_match: 1 } }
  },
  {
    name: 'No thresholds',
    input: undefined,
    expected: { thresholds: undefined }
  },
  {
    name: 'Malformed threshold (no equals)',
    input: 'exact_match.9',
    expected: { thresholds: undefined, error: 'Malformed threshold' }
  },
  {
    name: 'Malformed threshold (invalid value)',
    input: 'exact_match=abc',
    expected: { thresholds: undefined, error: 'Malformed threshold' }
  },
  {
    name: 'Invalid threshold value (> 1)',
    input: 'exact_match=1.5',
    expected: { thresholds: undefined, error: 'Invalid threshold value' }
  },
  {
    name: 'Invalid threshold value (< 0)',
    input: 'exact_match=-0.1',
    expected: { thresholds: undefined, error: 'Invalid threshold value' }
  },
  {
    name: 'Unknown metric',
    input: 'unknown_metric=0.9',
    expected: { thresholds: undefined, error: 'Unknown metric' }
  }
];

let passed = 0;
let failed = 0;

tests.forEach(test => {
  const result = parseThresholds(test.input);

  // Check if expected result matches
  let success = true;

  if (test.expected.error) {
    // Check if error message contains the expected substring
    success = result.error && result.error.includes(test.expected.error);
  } else {
    // Check if thresholds match
    success = JSON.stringify(result.thresholds) === JSON.stringify(test.expected.thresholds);
  }

  if (success) {
    console.log(`✓ ${test.name}`);
    passed++;
  } else {
    console.log(`✗ ${test.name}`);
    console.log(`  Expected:`, test.expected);
    console.log(`  Got:`, result);
    failed++;
  }
});

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);

